CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('owner','student','teacher')),active INTEGER NOT NULL DEFAULT 1,preferences TEXT NOT NULL DEFAULT '{}',daily_limit INTEGER,created_at REAL NOT NULL);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,csrf TEXT NOT NULL,expires_at REAL NOT NULL);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY,window REAL NOT NULL,amount INTEGER NOT NULL);
CREATE TABLE model_configs(id TEXT PRIMARY KEY,slot TEXT NOT NULL CHECK(slot IN ('agent','extraction')),config TEXT NOT NULL,encrypted_key TEXT NOT NULL,created_at REAL NOT NULL);
CREATE TABLE active_models(slot TEXT PRIMARY KEY,config_id TEXT NOT NULL REFERENCES model_configs(id));
CREATE TABLE audit(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id TEXT,action TEXT NOT NULL,target TEXT,details TEXT NOT NULL DEFAULT '{}',created_at REAL NOT NULL);
CREATE TABLE documents(id TEXT PRIMARY KEY,title TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('book','exam','exercise_collection','reference')),subject TEXT NOT NULL,track TEXT NOT NULL,year TEXT,source TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'ACTIVE',published_version TEXT,owner_id TEXT NOT NULL REFERENCES users(id),created_at REAL NOT NULL);
CREATE TABLE versions(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id),sequence INTEGER NOT NULL,bookforge_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'UPLOADED',reviewer_id TEXT REFERENCES users(id),reviewed_at REAL,review_notes TEXT,snapshot_dir TEXT,warnings TEXT NOT NULL DEFAULT '[]',created_at REAL NOT NULL,UNIQUE(document_id,sequence));
CREATE TABLE published_nodes(id TEXT PRIMARY KEY,version_id TEXT NOT NULL REFERENCES versions(id),document_id TEXT NOT NULL REFERENCES documents(id),parent_id TEXT,kind TEXT NOT NULL,title TEXT NOT NULL,start_order INTEGER NOT NULL,end_order INTEGER NOT NULL,start_page INTEGER NOT NULL,end_page INTEGER NOT NULL,content_file TEXT NOT NULL,metadata TEXT NOT NULL);
CREATE INDEX nodes_version ON published_nodes(version_id,start_order);
CREATE TABLE published_assets(id TEXT PRIMARY KEY,version_id TEXT NOT NULL REFERENCES versions(id),document_id TEXT NOT NULL REFERENCES documents(id),node_id TEXT,pdf_page INTEGER NOT NULL,type TEXT NOT NULL,file TEXT NOT NULL,metadata TEXT NOT NULL);
CREATE VIRTUAL TABLE library_fts USING fts5(node_id UNINDEXED,version_id UNINDEXED,title,body,tokenize='unicode61 remove_diacritics 2');
CREATE TABLE conversations(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,overrides TEXT NOT NULL DEFAULT '{}',created_at REAL NOT NULL,updated_at REAL NOT NULL);
CREATE TABLE messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN ('user','assistant')),content TEXT NOT NULL,blocks TEXT NOT NULL DEFAULT '[]',sources TEXT NOT NULL DEFAULT '[]',active INTEGER NOT NULL DEFAULT 1,created_at REAL NOT NULL);
CREATE INDEX messages_chat ON messages(conversation_id,created_at);
CREATE TABLE agent_runs(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),message_id TEXT NOT NULL REFERENCES messages(id),config_id TEXT NOT NULL REFERENCES model_configs(id),status TEXT NOT NULL DEFAULT 'QUEUED',cancel_requested INTEGER NOT NULL DEFAULT 0,lease_token TEXT,lease_until REAL,attempts INTEGER NOT NULL DEFAULT 0,error TEXT,steps INTEGER NOT NULL DEFAULT 0,tool_calls INTEGER NOT NULL DEFAULT 0,created_at REAL NOT NULL,finished_at REAL);
CREATE UNIQUE INDEX one_active_chat_run ON agent_runs(conversation_id) WHERE status IN ('QUEUED','RUNNING');
CREATE TABLE run_events(id INTEGER PRIMARY KEY AUTOINCREMENT,run_id TEXT NOT NULL REFERENCES agent_runs(id) ON DELETE CASCADE,type TEXT NOT NULL,payload TEXT NOT NULL,created_at REAL NOT NULL);
CREATE INDEX run_events_cursor ON run_events(run_id,id);
CREATE TABLE model_usage(id INTEGER PRIMARY KEY AUTOINCREMENT,run_id TEXT REFERENCES agent_runs(id) ON DELETE CASCADE,user_id TEXT NOT NULL,config_id TEXT NOT NULL,model TEXT NOT NULL,input_tokens INTEGER,output_tokens INTEGER,cached_tokens INTEGER,estimated_cost REAL,duration_ms REAL NOT NULL,created_at REAL NOT NULL);
CREATE TABLE loaded_context(conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,node_id TEXT NOT NULL REFERENCES published_nodes(id),version_id TEXT NOT NULL,loaded_at REAL NOT NULL,PRIMARY KEY(conversation_id,node_id));
